/* A deleted website page, its theme settings and its code files can be put back (round AY, run after part 66, run any time). Part 66 keeps a copy of every deleted row of the tables that hold creators' work in public.deleted_rows for 90 days, with public.storelib_restore_deleted_row(id) to put one back, and it lists store_theme_installs, but none of the tables that hold what a website actually is: store_theme_pages (every page's sections, draft and live), store_theme_settings (the theme's settings) and store_theme_custom_files (code written in the code editor or by the AI). Deleting a page in the editor (DELETE /api/website-builder/themes/[installId]/sections) removed its row for good, and deleting a website kept a copy of the install row only, while the database's cascade took every page, setting and code file with it, so putting the install back gave an empty website. This adds the same trigger part 66 uses to those three tables; nothing else changes. It does NOT cover store_theme_backups or site_releases (they are pruned on every AI task and publish, by design) or the AI chat tables (a conversation a person deletes is meant to go). No row is changed. LOCKS: CREATE TRIGGER takes a short lock on each of the three tables. Where part 66 has not run, or a table is not there, it is skipped with a notice. Safe to run again. */
DO $do$ DECLARE t text; BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL OR to_regclass('public.deleted_rows') IS NULL THEN RAISE NOTICE 'website deleted rows: part 66 has not run, so there is nothing to keep copies in yet.'; RETURN; END IF; FOREACH t IN ARRAY ARRAY['store_theme_pages', 'store_theme_settings', 'store_theme_custom_files'] LOOP IF to_regclass('public.' || t) IS NULL THEN RAISE NOTICE 'website deleted rows: % is not there, skipped.', t; CONTINUE; END IF; EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_keep_deleted', t); EXECUTE format('CREATE TRIGGER %I AFTER DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row()', t || '_keep_deleted', t); END LOOP; END $do$;
notify pgrst, 'reload schema';
